    const idx=src.indexOf("tl.set(", i);
    if(idx<0){ out+=src.slice(i); break; }
    out+=src.slice(i, idx);
    let j=idx+"tl.set(".length, depth=1, inStr=null;
    while(j<src.length && depth>0){
      const ch=src[j];
      if(inStr){ if(ch==="\\"){ j+=2; continue; } if(ch===inStr) inStr=null; }
      else if(ch==="\"" || ch==="\x27") inStr=ch;
      else if(ch==="(") depth++;
      else if(ch===")") depth--;
      j++;
    }
    const args=stripTrailingZero(src.slice(idx+"tl.set(".length, j-1));
    out+="gsap.set("+args+")";
    i=j;
  }
  return out;
}
